  ? await collectSceneDiagnostics(findManagedScene(GHOST_SHIP_KEY), {
      pointProbe: this.diagnosticPointProbe?.dom ?? null,
      canvasPointProbe: this.diagnosticPointProbe?.canvas ?? null
    })
  : null;

